# LIB_INTAKE_TO_JMOD S6: the comment block that precedes every generated module declaration. One source of truth for
# lib_intake.sh (new intakes) and relayout_module_info.sh (committed layers). JDK standard: lines within 100 columns,
# and the module declaration carries a doc comment, as the JDK's own module-info files do (javac -Xdoclint).
# Usage: module_info_header.sh <lib>
set -euo pipefail
printf '%s\n' \
    '/*' \
    ' * GENERATED by m3/tooling/lib-intake/lib_intake.sh (pattern LIB_INTAKE_TO_JMOD v2): requires' \
    ' * from jdeps, every package exported, upstream uses/provides kept and name-mapped.' \
    ' */' \
    '' \
    '/**' \
    " * Defines the {@code $1} library," \
    ' * relocated into M3JDK21 by LIB_INTAKE_TO_JMOD.' \
    ' */'
